      .then((value) => {
        if (active()) setSession(value);
      })
      .catch(() => {
        if (active()) setSession(null);
      })
      .finally(() => {
        if (active()) setLoading(false);
      });
    return () => controller.abort();
  }, []);
  return (
    <AuthContext.Provider value={{ session, loading, update }}>
      {children}
    </AuthContext.Provider>
